/* ============================================================
   DOCVIEW
============================================================ */

.doc-view-wrapper {
	max-width: 1180px;
	margin: 0 auto;
	padding: 28px 32px 48px;
	color: var(--text-color);
}


/* ============================================================
   HEADER
============================================================ */

.doc-view-header {
	display: flex;
	align-items: center;
	justify-content: space-between;
	gap: 24px;
	margin-bottom: 20px;
}

.doc-view-header-left {
	min-width: 0;
}

.doc-view-eyebrow {
	margin-bottom: 5px;
	font-size: 11px;
	font-weight: 600;
	color: var(--text-muted);
	text-transform: uppercase;
	letter-spacing: 0.08em;
}

.doc-view-title {
	margin: 0;
	font-size: 24px;
	line-height: 1.2;
	font-weight: 700;
	color: var(--heading-color, var(--text-color));
}

.doc-view-status {
	display: inline-flex;
	margin-top: 8px;
}

.doc-view-status-badge {
	display: inline-flex;
	align-items: center;
	padding: 3px 9px;
	border-radius: 999px;
	font-size: 11px;
	font-weight: 600;
}

.doc-view-status-submitted {
	background: var(--bg-green);
	color: var(--text-green);
}

.doc-view-status-draft {
	background: var(--bg-yellow);
	color: var(--text-yellow);
}

.doc-view-status-cancelled {
	background: var(--bg-red);
	color: var(--text-red);
}

.doc-view-header-actions {
	display: flex;
	align-items: center;
	gap: 6px;
	flex-shrink: 0;
}


/* ============================================================
   FULL FORM BUTTON
============================================================ */

.doc-view-open-form-btn {
	display: inline-flex;
	align-items: center;
	justify-content: center;

	width: 32px;
	height: 32px;

	padding: 0;

	border: 0;
	border-radius: 7px;

	background: transparent;
	color: var(--text-muted);

	cursor: pointer;
}

.doc-view-open-form-btn:hover {
	background: var(--bg-light-gray);
	color: var(--text-color);
}

.doc-view-open-form-btn:focus {
	outline: none;
	box-shadow: none;
}

.doc-view-open-form-btn svg {
	width: 17px;
	height: 17px;
}


/* ============================================================
   MAIN CARD
============================================================ */

.doc-view-main-card {
	background: var(--card-bg, var(--bg-color));
	border: 1px solid var(--border-color);
	border-radius: 10px;
	overflow: hidden;
}


/* ============================================================
   PARTIES
============================================================ */

.doc-view-parties {
	display: grid;
	grid-template-columns: repeat(3, 1fr);
}

.doc-view-party {
	padding: 18px 20px;
	min-width: 0;
}

.doc-view-party + .doc-view-party {
	border-left: 1px solid var(--border-color);
}

.doc-view-party-label {
	margin-bottom: 7px;
	font-size: 11px;
	font-weight: 600;
	color: var(--text-muted);
	text-transform: uppercase;
	letter-spacing: 0.05em;
}

.doc-view-party-name {
	font-size: 14px;
	font-weight: 600;
	color: var(--heading-color, var(--text-color));
}

.doc-view-party-secondary {
	margin-top: 4px;
	font-size: 12px;
	color: var(--text-muted);
}

.doc-view-party-address {
	margin-top: 8px;
	font-size: 12px;
	line-height: 1.55;
	color: var(--text-muted);
	white-space: pre-line;
}

.doc-view-party-detail {
	display: flex;
	gap: 6px;
	margin-top: 7px;
	font-size: 12px;
}

.doc-view-party-detail strong {
	font-weight: 600;
	color: var(--text-color);
}


/* ============================================================
   DISPATCH
============================================================ */

.doc-view-dispatch {
	display: flex;
	align-items: center;
	padding: 12px 20px;
	border-top: 1px solid var(--border-color);
	border-bottom: 1px solid var(--border-color);
	background: var(--subtle-fg);
}

.doc-view-dispatch-label {
	font-size: 10px;
	font-weight: 600;
	color: var(--text-muted);
	text-transform: uppercase;
	letter-spacing: 0.05em;
}

.doc-view-dispatch-value {
	margin-top: 2px;
	font-size: 12px;
	font-weight: 500;
}


/* ============================================================
   META
============================================================ */

.doc-view-meta {
	display: grid;
	grid-template-columns: repeat(4, 1fr);
	border-top: 1px solid var(--border-color);
}

.doc-view-meta-item {
	padding: 14px 20px;
}

.doc-view-meta-item + .doc-view-meta-item {
	border-left: 1px solid var(--border-color);
}

.doc-view-meta-label {
	font-size: 10px;
	font-weight: 600;
	color: var(--text-muted);
	text-transform: uppercase;
	letter-spacing: 0.04em;
}

.doc-view-meta-value {
	margin-top: 4px;
	font-size: 13px;
	font-weight: 500;
}


/* ============================================================
   SECTIONS
============================================================ */

.doc-view-section {
	margin-top: 18px;
	background: var(--card-bg, var(--bg-color));
	border: 1px solid var(--border-color);
	border-radius: 10px;
	overflow: hidden;
}

.doc-view-section-header {
	display: flex;
	align-items: center;
	justify-content: space-between;
	padding: 14px 18px;
	border-bottom: 1px solid var(--border-color);
}

.doc-view-section-title {
	font-size: 13px;
	font-weight: 600;
}

.doc-view-section-count {
	font-size: 11px;
	color: var(--text-muted);
}


/* ============================================================
   ITEMS
============================================================ */

.doc-view-items-wrapper {
	overflow-x: auto;
}

.doc-view-items {
	width: 100%;
	border-collapse: collapse;
}

.doc-view-items th {
	padding: 10px 12px;
	background: var(--subtle-fg);
	color: var(--text-muted);
	font-size: 10px;
	font-weight: 600;
	text-align: left;
	white-space: nowrap;
}

.doc-view-items td {
	padding: 12px;
	border-top: 1px solid var(--border-color);
	font-size: 12px;
	vertical-align: top;
}

.doc-view-items tbody tr:hover {
	background: var(--highlight-color);
}

.doc-view-item-name {
	font-weight: 600;
	color: var(--text-color);
}

.doc-view-item-description {
	margin-top: 3px;
	font-size: 11px;
	color: var(--text-muted);
}

.doc-view-number {
	text-align: right !important;
	white-space: nowrap;
}

.doc-view-amount {
	font-weight: 600;
}


/* ============================================================
   SUMMARY
============================================================ */

.doc-view-summary-grid {
	display: grid;
	grid-template-columns: 1.4fr 1fr;
	gap: 18px;
	margin-top: 18px;
}

.doc-view-summary-card {
	background: var(--card-bg, var(--bg-color));
	border: 1px solid var(--border-color);
	border-radius: 10px;
	overflow: hidden;
}

.doc-view-summary-header {
	padding: 14px 18px;
	border-bottom: 1px solid var(--border-color);
	font-size: 13px;
	font-weight: 600;
}


/* ============================================================
   GST
============================================================ */

.doc-view-gst-table {
	width: 100%;
	border-collapse: collapse;
}

.doc-view-gst-table th {
	padding: 9px 12px;
	background: var(--subtle-fg);
	color: var(--text-muted);
	font-size: 10px;
	font-weight: 600;
	text-align: left;
}

.doc-view-gst-table td {
	padding: 10px 12px;
	border-top: 1px solid var(--border-color);
	font-size: 12px;
}


/* ============================================================
   TOTALS
============================================================ */

.doc-view-total-table {
	padding: 8px 18px 4px;
}

.doc-view-total-row {
	display: flex;
	align-items: center;
	justify-content: space-between;
	gap: 20px;
	padding: 10px 0;
	border-bottom: 1px solid var(--border-color);
	font-size: 12px;
}

.doc-view-total-label {
	color: var(--text-muted);
}

.doc-view-total-value {
	font-weight: 500;
	text-align: right;
}

.doc-view-total-grand {
	margin-top: 3px;
	padding: 14px 0;
	border-bottom: 0;
	font-size: 15px;
	font-weight: 700;
}

.doc-view-total-grand .doc-view-total-label {
	color: var(--text-color);
}

.doc-view-total-grand .doc-view-total-value {
	font-weight: 700;
}

.doc-view-amount-words {
	margin: 0 18px 18px;
	padding-top: 12px;
	border-top: 1px solid var(--border-color);
}

.doc-view-amount-words-label {
	font-size: 10px;
	color: var(--text-muted);
}

.doc-view-amount-words-value {
	margin-top: 4px;
	font-size: 11px;
	font-weight: 500;
	line-height: 1.5;
}


/* ============================================================
   ACTIONS
============================================================ */

.doc-view-actions {
	display: flex;
	align-items: center;
	gap: 8px;
	margin-top: 18px;
}

.doc-view-action-btn {
	display: inline-flex;
	align-items: center;
	gap: 7px;

	padding: 8px 12px;

	border: 1px solid var(--border-color);
	border-radius: 7px;

	background: var(--card-bg, var(--bg-color));
	color: var(--text-color);

	font-size: 12px;
	font-weight: 500;

	cursor: pointer;
}

.doc-view-action-btn:hover {
	background: var(--bg-light-gray);
}

.doc-view-action-btn svg {
	width: 14px;
	height: 14px;
}


/* ============================================================
   RESPONSIVE
============================================================ */

@media (max-width: 900px) {

	.doc-view-wrapper {
		padding: 20px;
	}

	.doc-view-parties {
		grid-template-columns: 1fr;
	}

	.doc-view-party + .doc-view-party {
		border-left: 0;
		border-top: 1px solid var(--border-color);
	}

	.doc-view-meta {
		grid-template-columns: 1fr 1fr;
	}

	.doc-view-meta-item:nth-child(3) {
		border-left: 0;
		border-top: 1px solid var(--border-color);
	}

	.doc-view-meta-item:nth-child(4) {
		border-top: 1px solid var(--border-color);
	}

	.doc-view-summary-grid {
		grid-template-columns: 1fr;
	}
}

@media (max-width: 600px) {

	.doc-view-wrapper {
		padding: 14px;
	}

	.doc-view-title {
		font-size: 20px;
	}

	.doc-view-meta {
		grid-template-columns: 1fr;
	}

	.doc-view-meta-item + .doc-view-meta-item {
		border-left: 0;
		border-top: 1px solid var(--border-color);
	}

	.doc-view-actions {
		flex-wrap: wrap;
	}
}

